    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    if (out_master)
        *out_master = idl_m->hs[0];
    else
        drv_handle_close(idl_m->hs[0]);
    if (out_ctl)
        *out_ctl = idl_m->hs[1];
    else
        drv_handle_close(idl_m->hs[1]);
    if (out_proc)
        *out_proc = idl_m->hs[2];
    else
        drv_handle_close(idl_m->hs[2]);
